export function learningSources({T}){
 return `<div class="page-heading"><p class="eyebrow">YOMU</p><h1 tabindex="-1">${T('Kelime ve kanji kaynakları','Vocabulary and kanji sources')}</h1></div><div class="sources-page"><section class="panel"><h2>Kelime okunuşları · JMdict</h2><p>${T('Kasım kelime ekindeki 100 yazım/okunuş çifti JMdict ile karşılaştırıldı. Kısa Türkçe/İngilizce çalışma anlamları ve örnek cümleler Yomu için özgün hazırlandı. Düzeyler yaklaşık çalışma bantlarıdır; sözlük eşleşmesi bütün örneklerin insan editörü tarafından onaylandığı anlamına gelmez.','The 100 written-form/reading pairs in the November word expansion were checked against JMdict. Short Turkish/English study glosses and example sentences were originally prepared for Yomu. Levels are approximate study bands; dictionary matching does not mean all examples have human editorial approval.')}</p><p>© James William Breen / Electronic Dictionary Research and Development Group · <a href="https://www.edrdg.org/jmdict/j_jmdict.html" target="_blank" rel="noopener noreferrer">JMdict</a> · <a href="https://www.edrdg.org/edrdg/licence.html" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0 / EDRDG</a></p></section><section class="panel"><h2>KANJIDIC2 / EDRDG</h2><p>${T('Karakter anlamları ve on/kun okunuşları kanjiapi.dev üzerinden KANJIDIC2 verisinden alınır. Anlamlar kaynak dilindeki İngilizceyle gösterilir; otomatik çeviriyle doğrulanmış gibi sunulmaz. © James William Breen ve Electronic Dictionary Research and Development Group.','Character meanings and on/kun readings come from KANJIDIC2 through kanjiapi.dev. Meanings remain in the source English and are not presented as verified automatic translations. © James William Breen and the Electronic Dictionary Research and Development Group.')}</p><p><a href="https://www.edrdg.org/kanjidic/kanjd2index_legacy.html" target="_blank" rel="noopener noreferrer">KANJIDIC2</a> · <a href="https://www.edrdg.org/edrdg/licence.html" target="_blank" rel="noopener noreferrer">CC BY-SA 4.0 / EDRDG</a> · <a href="https://kanjiapi.dev/" target="_blank" rel="noopener noreferrer">kanjiapi.dev</a></p></section><section class="panel"><h2>KanjiVG</h2><p>${T('İşaretlenmiş yazım bileşenleri KanjiVG SVG verisinden okunur. Bu, tarihsel köken veya bileşenlerin seslerini yan yana ekleme kuralı değildir. Kısmi veya eksik ayrıştırmalar ayrıca etiketlenir. © Ulrich Apel ve KanjiVG katkıcıları; gösterilen türetilmiş yapı bilgisi CC BY-SA 3.0 kapsamındadır.','Labelled writing components are read from KanjiVG SVG data. They are not etymologies or rules for concatenating component sounds. Partial or incomplete breakdowns are labelled. © Ulrich Apel and KanjiVG contributors; the displayed derived structure is under CC BY-SA 3.0.')}</p><p><a href="https://kanjivg.tagaini.net/" target="_blank" rel="noopener noreferrer">KanjiVG</a> · <a href="https://kanjivg.tagaini.net/svg-format.html" target="_blank" rel="noopener noreferrer">${T('Veri biçimi','Data format')}</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 3.0</a></p></section><section class="panel"><h2>Kanjipedia</h2><p>${T('Yalnızca 語, 校 ve 時 için Kanjipedia’dan kontrol edilmiş, kısa ve kaynak bağlantılı oluşum notları bulunur. Diğer karakterler için tarihsel köken tahmin edilmez. Kanjipedia, Japonya Kanji Yeterlilik Testi Vakfı tarafından sunulur; oluşum notlarında kaynak olarak belirtilen sözlük 角川新字源 改訂新版’dir.','Only 語, 校 and 時 have short construction notes checked against linked Kanjipedia entries. Etymologies for other characters are not guessed. Kanjipedia is provided by the Japan Kanji Aptitude Testing Foundation; its construction notes cite 角川新字源 改訂新版.')}</p></section><section class="panel"><h2>${T('Kapsam ve bağlantı','Scope and connection')}</h2><p>${T('Bilgi panelini açtığında yalnızca seçilen karakter kanjiapi.dev ve KanjiVG’nin GitHub dosya hizmetine gönderilir. İnternet gerekir; aynı karakterin sonucu bu sayfa oturumunda en fazla 24 saat önbellekte tutulur. Kaynak yanıt vermezse bilgi tahmin edilmez. Sözlük verileri de hata içerebilir; kaynaklar yüzde yüz hatasızlık garantisi vermez.','Opening the panel sends only the selected character to kanjiapi.dev and KanjiVG’s GitHub file service. Internet is required; results are cached in this page session for at most 24 hours. Missing data is not guessed. Dictionary sources can also contain errors and do not guarantee perfect accuracy.')}</p><a class="btn secondary" href="#vocabulary">${T('Kelimelere dön','Back to vocabulary')}</a></section></div>`;
}
